#!/usr/bin/env bash
# Tier 1 (Python always; Rust when `cargo` is on PATH, Tier 2 REQUIRES it: VBM_SSE_REQUIRE_CARGO=1): the generated language bindings.
#   1. The committed bindings equal what scripts/gen-bindings.sh regenerates from abi/vbm_sse.abi.json (drift check), shown able to fail: each tampered generated file, and a missing one, is rejected.
#   2. libvbm_sse.so is built (scripts/build_shared.sh); the shared vectors (vbm-sse-vectors-1, generated by the Lean REFERENCE) run through the Python binding (tests/bindings/test_python.py) and the Rust binding
#      (bindings/rust/tests/vectors.rs): every row on every cut, the events, the last event ID and the reconnection time equal the reference's.
#   3. NEGATIVE self-tests: a corrupted expected event, last event ID and reconnection time each fail each binding's test; mutants of each generated report reader each fail it.
# Run: mise exec -- scripts/test_bindings.sh
set -euo pipefail
cd "$(dirname "$0")/.."
. scripts/lib-ran.sh   # ran_case / ran_done / must_fail: the self-tests count what they executed and a refused tool is a failure (docs/decisions/0002-ran-evidence.md)
tmp=$(mktemp -d); trap 'rm -rf "$tmp"' EXIT
export PYTHONDONTWRITEBYTECODE=1
changed() { cmp -s "$1" "$2" && { echo "test_bindings: self-test: the corruption of $3 changed nothing" >&2; exit 1; } || true; }

# 1. the drift check
scripts/gen-bindings.sh --check; ran_case
gen=(bindings/python/vbm_sse/_generated.py bindings/python/vbm_sse/__init__.py bindings/rust/src/sys.rs bindings/rust/src/lib.rs)
for f in "${gen[@]}"; do
  [ -f "$f" ] || { echo "test_bindings: $f is missing" >&2; exit 1; }
  rm -rf "$tmp/drift"; mkdir -p "$tmp/drift"; cp -r bindings "$tmp/drift/"
  echo "# drift" >> "$tmp/drift/$f"
  must_fail "a tampered $f" scripts/gen-bindings.sh --check "$tmp/drift"
  rm "$tmp/drift/$f"
  must_fail "a missing $f" scripts/gen-bindings.sh --check "$tmp/drift"
done
echo "test_bindings: the committed bindings equal the regenerated ones; a tampered or missing generated file each fails the drift check"

# 2. the library and the vectors
scripts/build_shared.sh "$tmp/lib" >/dev/null
lake build vbm-sse-vectors >/dev/null
lake exe vbm-sse-vectors --n 3 --out "$tmp/v.jsonl" >/dev/null 2>&1
v="$tmp/v.jsonl"
export VBM_SSE_LIB="$tmp/lib/libvbm_sse.so"
py() { python3 tests/bindings/test_python.py "$1" "${2:-bindings/python}"; }
py "$v"; ran_case   # the positive run: the control of the negative self-tests below
# 3. negative self-tests, Python
sed '0,/"events":\[{"type":"6d657373616765"/s//"events":[{"type":"6d657373616766"/' "$v" > "$tmp/c1.jsonl"; changed "$v" "$tmp/c1.jsonl" "an event type"
sed '0,/"last_event_id":"[0-9a-f]*","retry"/s//"last_event_id":"ff","retry"/' "$v" > "$tmp/c2.jsonl"; changed "$v" "$tmp/c2.jsonl" "a last event ID"
sed '0,/"retry":18446744073709551615/s//"retry":18446744073709551614/' "$v" > "$tmp/c3.jsonl"; changed "$v" "$tmp/c3.jsonl" "the saturated reconnection time"
for i in 1 2 3; do must_fail "python: corrupted row set $i" py "$tmp/c$i.jsonl"; done
pymutant() {  # pymutant NAME SED: a mutant of the generated Python report reader must fail the vectors
  rm -rf "$tmp/m_$1"; mkdir -p "$tmp/m_$1"; cp -r bindings/python/vbm_sse "$tmp/m_$1/"
  sed -i "$2" "$tmp/m_$1/vbm_sse/_generated.py"; changed bindings/python/vbm_sse/_generated.py "$tmp/m_$1/vbm_sse/_generated.py" "python mutant $1"
  must_fail "python mutant $1" py "$v" "$tmp/m_$1"
}
pymutant retryset 's/retry if retry_set == 1 else None/retry if retry_set == 0 else None/'
pymutant order 's/events.append(Event(take(tl), take(dl), take(il)))/events.append(Event(take(dl), take(tl), take(il)))/'
pymutant words 's/count, retry_set, retry, id_len = word(), word(), word(), word()/count, retry_set, id_len, retry = word(), word(), word(), word()/'
pymutant errcode 's/^ARG = 1/ARG = 9/'
echo "test_bindings: python: corrupted event, last event ID and reconnection time and four reader mutants each fail"

# 4. Rust
if ! command -v cargo >/dev/null 2>&1; then
  if [ -n "${VBM_SSE_REQUIRE_CARGO:-}" ]; then echo "test_bindings: cargo is required here (Tier 2) and was not found" >&2; exit 1; fi
  echo "test_bindings: rust SKIPPED: cargo was not found on PATH (Tier 1 skips it on a host without it)"; ran_done test_bindings; echo "test_bindings: ok (python only)"; exit 0
fi
export CARGO_TARGET_DIR="$tmp/target" CARGO_BUILD_JOBS=2 VBM_SSE_LIB_DIR="$tmp/lib"
rs() { VBM_SSE_VECTORS="$1" cargo test --quiet --offline --manifest-path "${2:-bindings/rust}/Cargo.toml" -- --nocapture; }
rs "$v" 2>&1 | grep -E 'vectors: [0-9]+ rows' || { echo "test_bindings: the rust vectors test did not report" >&2; exit 1; }; ran_case
for i in 1 2 3; do must_fail "rust: corrupted row set $i" rs "$tmp/c$i.jsonl"; done
rsmutant() {  # rsmutant NAME FILE SED
  rm -rf "$tmp/r_$1"; mkdir -p "$tmp/r_$1"; cp -r bindings/rust/. "$tmp/r_$1/"
  sed -i "$3" "$tmp/r_$1/$2"; changed "bindings/rust/$2" "$tmp/r_$1/$2" "rust mutant $1"
  must_fail "rust mutant $1" rs "$v" "$tmp/r_$1"
}
rsmutant retryset src/lib.rs 's/retry: if retry_set == 1 { Some(retry) } else { None }/retry: if retry_set == 0 { Some(retry) } else { None }/'
rsmutant order src/lib.rs 's/events.push(Event { type_: c.take(tl)?, data: c.take(dl)?, last_event_id: c.take(il)? });/events.push(Event { type_: c.take(dl)?, data: c.take(tl)?, last_event_id: c.take(il)? });/'
rsmutant words src/lib.rs 's/let (count, retry_set, retry, id_len) = (c.word()?, c.word()?, c.word()?, c.word()?);/let (count, retry_set, id_len, retry) = (c.word()?, c.word()?, c.word()?, c.word()?);/'
rsmutant errcode src/sys.rs 's/^pub const VBM_SSE_ARG: c_int = 1;/pub const VBM_SSE_ARG: c_int = 9;/'
echo "test_bindings: rust: corrupted event, last event ID and reconnection time and four reader mutants each fail"
ran_done test_bindings
echo "test_bindings: ok"
